setName.example:
// client
const { Discord } = kcds.ui;

Discord.setName('Rattay Roleplay');
Discord.update();

setState.example:
// client
const { Discord } = kcds.ui;

kcds.core.Events.on('job:changed', (job) => {
  Discord.setState(`Working as a ${job}`);
  Discord.update();
});

setState.exampleCs:
// client

Events.On("job:changed", (JsValue job) =>
{
    Discord.SetState($"Working as a {job}");
    Discord.Update();
});

