setButton.example:
// client
const { Discord } = kcds.ui;

Discord.setButton('Join our Discord', 'https://discord.gg/example');
Discord.update();

setPresence.example:
// client
const published = kcds.ui.Discord.setPresence({
  state: 'Hunting near Ledetchko',
  smallImage: 'https://example.com/icons/bow.png',
  smallText: 'Hunter',
});
if (!published) {
  console.log('Discord is not running');
}

setPresence.exampleCs:
// client
var published = Discord.SetPresence(new { state = "Hunting near Ledetchko", smallImage = "https://example.com/icons/bow.png", smallText = "Hunter" });
if (!published)
{
    Log.Info("Discord is not running");
}

update.example:
// client
const { Discord } = kcds.ui;

Discord.setState('At the Rattay market');
Discord.update();

update.exampleCs:
// client

Discord.SetState("At the Rattay market");
Discord.Update();

getUserId.example:
// client
const discordId = kcds.ui.Discord.getUserId();
if (discordId) {
  kcds.core.Events.toServer('profile:discord', { discordId });
}

getUserId.exampleCs:
// client
var discordId = Discord.GetUserId();
if (!string.IsNullOrEmpty(discordId))
{
    Events.ToServer("profile:discord", new { discordId = discordId });
}

isAvailable.example:
// client
const { Discord } = kcds.ui;

if (Discord.isAvailable()) {
  Discord.setState('In a duel');
  Discord.update();
}

isAvailable.exampleCs:
// client

if (Discord.IsAvailable())
{
    Discord.SetState("In a duel");
    Discord.Update();
}
